<span class="line"><span style="color:#C678DD;">    public</span><span style="color:#C678DD;"> async</span><span style="color:#E5C07B;"> Task</span><span style="color:#61AFEF;"> InitializeModulesAsync</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">ApplicationInitializationContext</span><span style="color:#E5C07B;"> context</span><span style="color:#ABB2BF;">)</span></span>
